"""JSON Helper TEST-only consumer: compare actual wire result, then forward image ref."""
import json
import math
from comfy_api.latest import io

def same_json(actual, expected):
    if type(actual) is not type(expected):
        return False
    if isinstance(expected, dict):
        return actual.keys() == expected.keys() and all(same_json(actual[k], v) for k, v in expected.items())
    if isinstance(expected, list):
        return len(actual) == len(expected) and all(same_json(a, b) for a, b in zip(actual, expected))
    if isinstance(expected, float) and math.isnan(expected):
        return math.isnan(actual)
    return actual == expected

class MOEJSONHelperExpectedResult(io.ComfyNode):
    SDK_REFS = True
    SDK_PERMISSIONS = ()

    @classmethod
    def define_schema(cls):
        return io.Schema(
            node_id='MOEJSONHelperExpectedResult', category='tests/JSONHelper',
            inputs=[io.Custom('JSON').Input('actual'), io.String.Input('expected_json'), io.Image.Input('image')],
            outputs=[io.Image.Output()],
        )

    @classmethod
    def execute(cls, actual, expected_json, image):
        expected = json.loads(expected_json)
        if not same_json(actual, expected):
            raise AssertionError('JSON Helper TEST result differs from fixed expected value/type')
        return io.NodeOutput(image)
